use std::marker::PhantomData;

/// A typed handle to one column of a [`FletchSchema`](crate::FletchSchema)
/// struct, generated by `#[derive(FletchSchema)]` as one `pub const` per
/// field: `DaqRecord::TICKS` is a `Column<u64>`. An `Option<T>` field's handle
/// is a `Column<T>`.
///
/// With the `view` feature its methods build typed view predicates and sort
/// keys that accept only values of `T`.
pub struct Column<T> {
    name: &'static str,
    _marker: PhantomData<fn() -> T>,
}

impl<T> Column<T> {
    #[doc(hidden)]
    pub const fn new(name: &'static str) -> Self {
        Self {
            name,
            _marker: PhantomData,
        }
    }

    /// The column's name in the stream.
    pub const fn name(&self) -> &'static str {
        self.name
    }
}

impl<T> Clone for Column<T> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<T> Copy for Column<T> {}

impl<T> std::fmt::Debug for Column<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_tuple("Column").field(&self.name).finish()
    }
}

/// An owned value compared against a column in a typed view predicate.
#[doc(hidden)]
#[derive(Clone, Debug, PartialEq)]
pub enum ColumnLiteral {
    Bool(bool),
    U8(u8),
    U16(u16),
    U32(u32),
    U64(u64),
    I32(i32),
    I64(i64),
    F32(f32),
    F64(f64),
    Str(String),
}

/// A value a `Column<T>` can be compared with: a `T`, or a `&str` for a
/// `String` column. `#[derive(FletchEnum)]` implements it for the enum.
#[diagnostic::on_unimplemented(
    message = "a `Column<{T}>` cannot be compared with `{Self}`",
    label = "expected a `{T}` value"
)]
pub trait ColumnValue<T> {
    #[doc(hidden)]
    fn into_literal(self) -> ColumnLiteral;
}

/// Column types with a meaningful order, so `lt`, `le`, `gt`, `ge` and
/// `between` apply. Enum columns compare only for equality.
#[diagnostic::on_unimplemented(
    message = "`{Self}` columns have no order to compare by",
    note = "enum columns support `eq`, `ne` and `is_in`"
)]
pub trait OrderedColumn {}

macro_rules! column_value {
    ($($ty:ty => $variant:ident),*) => {
        $(
            impl ColumnValue<$ty> for $ty {
                fn into_literal(self) -> ColumnLiteral {
                    ColumnLiteral::$variant(self)
                }
            }

            impl OrderedColumn for $ty {}
        )*
    };
}

column_value!(
    bool => Bool,
    u8 => U8,
    u16 => U16,
    u32 => U32,
    u64 => U64,
    i32 => I32,
    i64 => I64,
    f32 => F32,
    f64 => F64,
    String => Str
);

impl ColumnValue<String> for &str {
    fn into_literal(self) -> ColumnLiteral {
        ColumnLiteral::Str(self.to_string())
    }
}

impl ColumnValue<String> for &String {
    fn into_literal(self) -> ColumnLiteral {
        ColumnLiteral::Str(self.clone())
    }
}
